<script setup lang="ts">
import { ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import FeatureLayout from '../../components/FeatureLayout.vue'
import { api } from '../../services/api'
import { config } from '../../config'
import type { Story } from '../../types/domain'
import { errorMessage, goPage, requireSession } from '../../utils/navigation'
const id=ref(''), story=ref<Story|null>(null), error=ref(''), busy=ref(false)
const labels={draft:'灵感草稿',generating:'创作中',ready:'已完成',failed:'草稿已保留'}
onLoad(q=>{id.value=String(q?.id||'')})
async function load(){if(!requireSession())return;error.value='';try{story.value=await api.story(id.value)}catch(e){error.value=errorMessage(e)}}
onShow(load)
async function generate(){if(busy.value||!story.value)return;busy.value=true;try{const task=await api.startGeneration(story.value.id);goPage('progress',{taskId:task.id})}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><FeatureLayout title="故事详情" :subtitle="story?.title"><view class="page-content"><view v-if="error" class="state-panel"><text class="error-copy">{{error}}</text><button class="warm-button" @tap="load">重新加载</button></view><template v-else-if="story"><view class="paper-panel detail-banner"><image :src="story.coverUrl" class="detail-cover" mode="aspectFill"/><view class="detail-heading"><text class="pill">{{labels[story.status]}}</text><text class="section-title serif">{{story.title}}</text><text class="small-note">{{story.genre}} · {{story.chapters?.length||0}} 章</text><text class="small-note">{{story.media?.actors.map(actor=>actor.name).join(' · ')||'墨羽 · 灵墨'}}</text></view></view><view class="section-gap"><text class="section-title serif">故事简介</text><text class="copy">{{story.idea}}</text></view><view v-if="story.chapters?.length" class="section-gap"><view class="row-between"><text class="section-title serif">章节目录</text><text class="small-note">共 {{story.chapters.length}} 章</text></view><button v-for="(chapter,index) in story.chapters" :key="chapter.id" class="chapter-row" @tap="goPage('reader',{id:story.id,chapter:index})"><text class="chapter-number">{{String(index+1).padStart(2,'0')}}</text><text>{{chapter.title}}</text><text class="chapter-arrow">›</text></button></view><button v-if="story.media" class="warm-button full-button" @tap="goPage('performance',{id:story.id})">观看演绎</button><button v-if="story.chapters?.length" class="primary-button full-button" @tap="goPage('reader',{id:story.id})">{{story.media?'阅读对白':'继续阅读'}}</button><button v-if="config.localBackend && story.status==='ready'" class="warm-button full-button" @tap="goPage('production',{id:story.id})">{{story.productionTaskId?'查看制作与审核':'制作配音与分镜'}}</button><view v-if="story.production" class="paper-panel section-gap"><text class="field-label">作品制作状态</text><text class="copy">{{story.production.message}}</text></view><button v-if="story.generationTaskId && story.status!=='ready'" class="warm-button full-button" @tap="goPage('progress',{taskId:story.generationTaskId})">查看创作进度 / 确认大纲</button><button v-if="!story.generationTaskId && story.status!=='ready'" class="warm-button full-button" :disabled="busy" :loading="busy" @tap="generate">{{story.status==='failed'?'重新生成':'开始生成'}}</button><button v-if="story.status==='draft'||story.status==='failed'" class="outline-button full-button" @tap="goPage('create',{id:story.id})">继续编辑灵感</button><text v-if="config.useMock" class="small-note spaced">本地体验：章节与演绎数据用于预览，尚未连接内容生成服务。</text></template><view v-else class="state-panel">正在翻开故事…</view></view></FeatureLayout></template>
<style scoped>.detail-banner{display:flex;gap:26rpx;align-items:center;padding:26rpx}.detail-cover{width:170rpx;height:224rpx;border-radius:20rpx}.detail-heading{flex:1;min-width:0}.detail-heading .section-title{font-size:43rpx;margin:18rpx 0 10rpx;overflow-wrap:anywhere}.chapter-row{display:flex;align-items:center;gap:22rpx;padding:28rpx 4rpx;border-bottom:2rpx solid #eadcc9;text-align:left}.chapter-number{color:#b99668;font-size:24rpx}.chapter-arrow{margin-left:auto;color:#b99668}</style>
